def _hex_to_node_color(hex_color):
    """Convert "#RRGGBB" to the 0-1 RGB values stored in node.color.
    Blender's color picker shows these values as hex directly (no gamma correction)."""
    hex_color = hex_color.lstrip("#")
    return tuple(int(hex_color[i:i + 2], 16) / 255.0 for i in (0, 2, 4))


def _find_group(main_name, source_name=None):
    """The main shader node group: the one with its final name, or (older imports) the one
    with its original name inside the embedded .blend. Only shader node groups count, so a
    Geometry Nodes group with the same name is never mistaken for it."""
    for name in (main_name, source_name):
        if not name:
            continue
        group = bpy.data.node_groups.get(name)
        if group is not None and group.bl_idname == 'ShaderNodeTree':
            return group
    return None


def _has_geometry_group(name):
    """True if the project already has a Geometry Nodes group with this name."""
    group = bpy.data.node_groups.get(name)
    return group is not None and group.bl_idname == 'GeometryNodeTree'


def _append_from_embedded(blob_name, group_filter, sun_name=""):
    """Append data from an embedded .blend (the base64 module variable blob_name).

    group_filter(names) returns the node group names to load from the file.
    Return (requested group names, loaded groups in the same order (None if missing), sun object or None).
    Blender can only read .blend data from a file, so the embedded copy goes to a temp file."""
    fd, path = tempfile.mkstemp(suffix=".blend")
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(base64.b64decode(globals()[blob_name]))

        requested = []
        with bpy.data.libraries.load(path, link=False) as (data_from, data_to):
            requested = list(group_filter(list(data_from.node_groups)))
            if requested:
                data_to.node_groups = requested
            if sun_name and sun_name in data_from.objects:
                data_to.objects = [sun_name]

        loaded = list(data_to.node_groups) if requested else []
        sun = data_to.objects[0] if (sun_name and data_to.objects) else None
        return requested, loaded, sun
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


def _nested_groups(tree, visited=None):
    """All node groups used (directly or nested) by a node tree."""
    if visited is None:
        visited = set()
    found = []
    for node in tree.nodes:
        if node.type == 'GROUP' and node.node_tree is not None and node.node_tree.name not in visited:
            visited.add(node.node_tree.name)
            found.append(node.node_tree)
            found += _nested_groups(node.node_tree, visited)
    return found


def _rename_groups(renames, groups, main_group):
    """Rename node groups according to the renames dict {old name: new name}.
    Applies to the groups just imported and to the ones used by the main group
    (so projects imported with an older version get the new name too)."""
    candidates = list(groups)
    if main_group is not None:
        candidates += _nested_groups(main_group)
    for grp in candidates:
        new_name = renames.get(grp.name)
        if new_name and new_name not in bpy.data.node_groups:
            grp.name = new_name


_PREVIEW_DUMMY_NAME = "material_preview_dummy"
_preview_dummy_ticks_left = 0


def _remove_preview_dummy():
    """Delete the 'material_preview_dummy' object and mesh that Blender creates when
    previewing the new material. They are not needed."""
    try:
        for obj in [o for o in bpy.data.objects if o.name.startswith(_PREVIEW_DUMMY_NAME)]:
            bpy.data.objects.remove(obj, do_unlink=True)
        for mesh in [m for m in bpy.data.meshes if m.name.startswith(_PREVIEW_DUMMY_NAME)]:
            if mesh.users == 0:
                bpy.data.meshes.remove(mesh)
    except Exception:
        pass


def _preview_dummy_tick():
    global _preview_dummy_ticks_left
    _remove_preview_dummy()
    _preview_dummy_ticks_left -= 1
    return 0.5 if _preview_dummy_ticks_left > 0 else None  # None stops the timer


def _schedule_preview_dummy_cleanup():
    """Blender may create the dummy a moment after the material is built, so keep
    checking for a few seconds."""
    global _preview_dummy_ticks_left
    _preview_dummy_ticks_left = 20  # about 10 seconds
    if not bpy.app.timers.is_registered(_preview_dummy_tick):
        bpy.app.timers.register(_preview_dummy_tick, first_interval=0.5)


def _strive_frame(tree, label):
    frame = tree.nodes.new("NodeFrame")
    frame.label = label
    return frame


def _strive_image_node(tree, name, frame, location, interpolation):
    """Empty Image Texture node (Flat / Repeat) inside a frame. The image is assigned by the user."""
    tex = tree.nodes.new("ShaderNodeTexImage")
    tex.name = name
    tex.interpolation = interpolation
    tex.projection = 'FLAT'
    tex.extension = 'REPEAT'
    tex.parent = frame
    tex.location = location
    return tex


def _strive_link(tree, out_socket, node, input_name):
    target = node.inputs.get(input_name)
    if target is not None:
        tree.links.new(out_socket, target)


def _build_strive_nodes(mat, group):
    """Build the Strive node setup of a material: texture nodes in labeled frames, the main
    Strive group, the Detail threshold + UV Map, a Contact Lighting node and the Material Output."""
    tree = mat.node_tree
    tree.nodes.clear()

    # Main shader group -> Material Output
    group_node = tree.nodes.new("ShaderNodeGroup")
    group_node.node_tree = group
    group_node.width = 400
    group_node.location = (0, 0)
    group_node.label = _STRIVE_MAIN_GROUP  # title shown on the node
    group_node.use_custom_color = True
    group_node.color = _hex_to_node_color(_STRIVE_GROUP_COLOR)

    output = tree.nodes.new("ShaderNodeOutputMaterial")
    output.location = (830, 20)

    shader_socket = next((sock for sock in group_node.outputs if sock.type == 'SHADER'), None)
    if shader_socket is not None:
        tree.links.new(shader_socket, output.inputs["Surface"])

    # Base
    frame = _strive_frame(tree, "Base (Color Space sRGB)")
    base = _strive_image_node(tree, "Base", frame, (-908, 630), 'Closest')
    _strive_link(tree, base.outputs["Color"], group_node, "Base")
    _strive_link(tree, base.outputs["Alpha"], group_node, "Base Alpha")

    # SSS
    frame = _strive_frame(tree, "SSS (Color Space sRGB)")
    sss = _strive_image_node(tree, "SSS", frame, (-906, 304), 'Closest')
    _strive_link(tree, sss.outputs["Color"], group_node, "SSS")
    _strive_link(tree, sss.outputs["Alpha"], group_node, "SSS Alpha")

    # ILM: a Closest node (left unconnected, as in the reference) and the Linear one that is used
    frame = _strive_frame(tree, "ILM (Color Space Linear)")
    _strive_image_node(tree, "ILM Closest", frame, (-1166, -28), 'Closest')
    ilm = _strive_image_node(tree, "ILM", frame, (-904, -28), 'Linear')
    _strive_link(tree, ilm.outputs["Color"], group_node, "ILM Linear")
    _strive_link(tree, ilm.outputs["Alpha"], group_node, "ILM Alpha")

    # Detail: image -> Greater Than (0.5) -> Detail, with a UV Map node for the second UV
    frame = _strive_frame(tree, "Detail (Color Space sRGB)")
    detail = _strive_image_node(tree, "Detail", frame, (-904, -362), 'Cubic')

    threshold = tree.nodes.new("ShaderNodeMath")
    threshold.operation = 'GREATER_THAN'
    threshold.inputs[1].default_value = 0.5
    threshold.location = (-580, -360)
    tree.links.new(detail.outputs["Color"], threshold.inputs[0])
    _strive_link(tree, threshold.outputs[0], group_node, "Detail")

    uv_frame = _strive_frame(tree, "Make sure the second UV is selected")
    uv_node = tree.nodes.new("ShaderNodeUVMap")
    uv_node.uv_map = "UVMap.001"
    uv_node.from_instancer = False
    uv_node.parent = uv_frame
    uv_node.location = (-1170, -522)
    tree.links.new(uv_node.outputs["UV"], detail.inputs["Vector"])

    # Contact Lighting: left unconnected, as in the reference
    contact_group = bpy.data.node_groups.get("Contact Lighting")
    if contact_group is not None:
        contact = tree.nodes.new("ShaderNodeGroup")
        contact.node_tree = contact_group
        contact.location = (474, 284)
        contact.use_custom_color = True
        contact.color = _hex_to_node_color(_STRIVE_CONTACT_COLOR)


def _build_xrd_nodes(mat, group):
    """Rebuild the Xrd material exactly like the one in the original Xrd file: Base / SSS / ILM
    texture nodes in labeled frames, the Xrd group (Color goes straight to the Material Output)
    and the three "Manual Dot" frames (Rotate Dot Vector -> Normal -> Dot)."""
    rotate_group = bpy.data.node_groups.get(_XRD_ROTATE_GROUP)
    if rotate_group is None:
        raise ValueError(f"node group '{_XRD_ROTATE_GROUP}' not found")

    tree = mat.node_tree
    tree.nodes.clear()

    frames = {}
    for label, location in _XRD_FRAMES:
        frame = _strive_frame(tree, label)
        frame.location = location
        frames[label] = frame

    # Main Xrd group -> Material Output
    group_node = tree.nodes.new("ShaderNodeGroup")
    group_node.node_tree = group
    group_node.width = 385
    group_node.location = (535, -245)
    group_node.use_custom_color = True
    group_node.color = _XRD_GROUP_COLOR
    for name, value in _XRD_GROUP_VALUES.items():
        socket = group_node.inputs.get(name)
        if socket is not None:
            try:
                socket.default_value = value
            except Exception:
                pass

    output = tree.nodes.new("ShaderNodeOutputMaterial")
    output.location = (1035, -225)
    color_socket = (group_node.outputs.get("Color")
                    or next((sock for sock in group_node.outputs if sock.type == 'RGBA'), None))
    if color_socket is not None:
        tree.links.new(color_socket, output.inputs["Surface"])

    # Base / SSS / ILM textures (empty: the images are assigned by the user)
    textures = (
        ("Base", "Base (Color Space sRGB)", "Base", "Base Alpha"),
        ("SSS", "SSS (Color Space sRGB)", "SSS", "SSS Alpha"),
        ("ILM", "ILM (Color Space Linear)", "ILM Linear", "ILM Alpha"),
    )
    for name, frame_label, color_input, alpha_input in textures:
        tex = _strive_image_node(tree, name, frames[frame_label], (31, -36), 'Linear')
        _strive_link(tree, tex.outputs["Color"], group_node, color_input)
        _strive_link(tree, tex.outputs["Alpha"], group_node, alpha_input)

    # Manual Dot frames: Rotate Dot Vector -> Normal -> Dot -> "<name> Manual Dot" input
    for dot_name in ("Rimlight", "Specular", "Light"):
        frame = frames[f"{dot_name} Manual Dot"]

        rotate = tree.nodes.new("ShaderNodeGroup")
        rotate.node_tree = rotate_group
        rotate.parent = frame
        rotate.width = 242
        rotate.location = (30, -96)
        rotate.use_custom_color = True
        rotate.color = _XRD_ROTATE_COLOR

        normal = tree.nodes.new("ShaderNodeNormal")
        normal.parent = frame
        normal.width = 127
        normal.location = (310, -36)

        vector_socket = (rotate.outputs.get("Vector")
                         or next((sock for sock in rotate.outputs if sock.type == 'VECTOR'), None))
        if vector_socket is not None:
            tree.links.new(vector_socket, normal.inputs["Normal"])
        _strive_link(tree, normal.outputs["Dot"], group_node, f"{dot_name} Manual Dot")


def _build_decal_nodes(mat, group):
    """Build the Decal/Damage material: a Decal texture node in its labeled frame connected to
    the Decal/Damage group, whose shader goes to the Material Output. The material is set to
    Blended, as the Fix Decal button does."""
    tree = mat.node_tree
    tree.nodes.clear()

    group_node = tree.nodes.new("ShaderNodeGroup")
    group_node.node_tree = group
    group_node.width = 300
    group_node.location = (0, 0)

    output = tree.nodes.new("ShaderNodeOutputMaterial")
    output.location = (450, 0)

    shader_socket = next((sock for sock in group_node.outputs if sock.type == 'SHADER'), None)
    if shader_socket is not None:
        tree.links.new(shader_socket, output.inputs["Surface"])

    # Empty image texture node: the image is assigned by the user
    frame = _strive_frame(tree, "Decal or Damage (Color Space Linear)")
    tex = _strive_image_node(tree, "Decal", frame, (-650, 0), 'Linear')
    _strive_link(tree, tex.outputs["Color"], group_node, "Decal/Damage")
    _strive_link(tree, tex.outputs["Alpha"], group_node, "Decal/Damage Alpha")

    _set_blended(mat)


def _build_outline_nodes(mat, group):
    """Rebuild the Outline material: SSS and OLM texture nodes in labeled frames feeding the
    Outline group (default node color), whose Cycles output goes to a Cycles Material Output
    and whose Eevee output goes through a collapsed "Disable Shadow" Mix Shader
    (Light Path Is Shadow Ray -> Transparent BSDF) to an Eevee Material Output."""
    tree = mat.node_tree
    tree.nodes.clear()

    # Textures (empty: the images are assigned by the user)
    frame = _strive_frame(tree, "SSS (Color Space sRGB)")
    frame.location = (-260.6, 479.5)
    sss = _strive_image_node(tree, "SSS", frame, (30.8, -36.6), 'Linear')

    frame = _strive_frame(tree, "OLM (Color Space Linear)")
    frame.location = (-261.8, 137.5)
    olm = _strive_image_node(tree, "OLM", frame, (30.5, -36.2), 'Linear')

    # Outline group
    group_node = tree.nodes.new("ShaderNodeGroup")
    group_node.node_tree = group
    group_node.width = 400
    group_node.location = (120.4, 371.5)
    for name, value in _OUTLINE_GROUP_VALUES.items():
        socket = group_node.inputs.get(name)
        if socket is not None:
            try:
                socket.default_value = value
            except Exception:
                pass

    _strive_link(tree, sss.outputs["Color"], group_node, "SSS")
    _strive_link(tree, sss.outputs["Alpha"], group_node, "SSS Alpha")
    _strive_link(tree, olm.outputs["Color"], group_node, "OLM")
    _strive_link(tree, olm.outputs["Alpha"], group_node, "OLM Alpha")

    # Cycles output (the group's output is spelled "Cyles" in the original file)
    cycles_output = tree.nodes.new("ShaderNodeOutputMaterial")
    cycles_output.target = 'CYCLES'
    cycles_output.location = (711.5, 442.1)
    cycles_output.is_active_output = True
    cycles_socket = group_node.outputs.get("Cyles") or group_node.outputs.get("Cycles")
    if cycles_socket is not None:
        tree.links.new(cycles_socket, cycles_output.inputs["Surface"])

    # Eevee output: Mix Shader that disables the shadow (Is Shadow Ray -> Transparent BSDF)
    eevee_output = tree.nodes.new("ShaderNodeOutputMaterial")
    eevee_output.target = 'EEVEE'
    eevee_output.location = (706.5, 288.6)

    # These three nodes are never edited, so they are collapsed and stacked at the same spot
    mix = tree.nodes.new("ShaderNodeMixShader")
    mix.label = "Disable Shadow"
    light_path = tree.nodes.new("ShaderNodeLightPath")
    transparent = tree.nodes.new("ShaderNodeBsdfTransparent")
    for node in (mix, light_path, transparent):
        node.location = (550.6, 261.2)
        node.hide = True

    eevee_socket = group_node.outputs.get("Eevee")
    if eevee_socket is not None:
        tree.links.new(eevee_socket, mix.inputs[1])
    tree.links.new(light_path.outputs["Is Shadow Ray"], mix.inputs[0])
    tree.links.new(transparent.outputs["BSDF"], mix.inputs[2])
    tree.links.new(mix.outputs["Shader"], eevee_output.inputs["Surface"])

    # Material settings of the original: backface culling and transparent shadows
    for attr in ("use_backface_culling", "use_transparent_shadow"):
        if hasattr(mat, attr):
            setattr(mat, attr, True)


def _apply_shader_material(group, obj, build, material_name):
    """Overwrite the active material of obj with a shader setup (build(mat, group)).

    The material keeps its name and stays assigned (so every object that shares it is
    affected). If the active slot is empty a new material called material_name is created
    and assigned. Without a usable object, the standalone material_name material is
    created (or overwritten) instead.
    Return (material, "created" or "overwritten")."""
    if obj is not None and getattr(obj.data, "materials", None) is not None:
        mat = obj.active_material
        if mat is None:
            mat = bpy.data.materials.new(material_name)
            if obj.material_slots:
                obj.active_material = mat
            else:
                obj.data.materials.append(mat)
            action = "created"
        else:
            action = "overwritten"
    else:
        mat = bpy.data.materials.get(material_name)
        action = "overwritten" if mat is not None else "created"
        if mat is None:
            mat = bpy.data.materials.new(material_name)
        mat.use_fake_user = True  # keep it when saving even if no object uses it yet

    if mat.library is not None:
        raise ValueError(f"material '{mat.name}' is linked from another file and can't be edited")

    if mat.node_tree is None:
        try:
            mat.use_nodes = True  # deprecated in recent versions, but harmless
        except Exception:
            pass
    if mat.node_tree is None:
        raise ValueError(f"material '{mat.name}' has no node tree")

    build(mat, group)
    return mat, action


class _ShaderImportOperator:
    """Shared logic of the shader import buttons. Subclasses set the attributes below."""
    shader_label = ""        # name used in messages
    blend_data_name = ""     # name of the module variable holding the embedded .blend (base64)
    main_group = ""          # final name of the main node group
    main_group_source = ""   # its name inside the embedded .blend
    sun_name = ""            # name of the Sun object to import
    material_name = ""       # name for a newly created material
    build_nodes = None       # function(mat, group) that builds the node setup
    group_renames = {}       # other node groups to rename after importing {old: new}
    rename_legacy_main = False       # rename an older import of the main group to its final name
    extra_blend_data_name = ""       # second embedded .blend with extra (Geometry Nodes) groups
    extra_groups = ()                # names of the groups to import from that file

    def execute(self, context):
        label = self.shader_label
        main_group = _find_group(self.main_group, self.main_group_source)

        # An older import kept the original name: give it the final one, which also frees
        # the original name for the Geometry Nodes group with that name
        if (self.rename_legacy_main and main_group is not None
                and main_group.name == self.main_group_source != self.main_group
                and self.main_group not in bpy.data.node_groups):
            main_group.name = self.main_group

        import_groups = main_group is None
        import_sun = bool(self.sun_name) and self.sun_name not in bpy.data.objects

        groups = []
        sun = None

        if import_groups or import_sun:
            def group_filter(names):
                if not import_groups:
                    return []
                return [name for name in names if name not in _STRIVE_SKIP_GROUPS]

            try:
                requested, loaded, sun = _append_from_embedded(
                    self.blend_data_name, group_filter, self.sun_name if import_sun else ""
                )
            except Exception as exc:
                self.report(
                    {'ERROR'},
                    f"Could not read the embedded {label} shader (saved with Blender 5.2): {exc}"
                )
                return {'CANCELLED'}

            groups = [grp for grp in loaded if grp is not None]
            if self.main_group_source and self.main_group_source != self.main_group:
                for name, grp in zip(requested, loaded):
                    if grp is not None and name == self.main_group_source:
                        grp.name = self.main_group

        # Extra Geometry Nodes groups (imported after the rename above, so their names are free)
        extra_groups = []
        if self.extra_blend_data_name:
            wanted = [name for name in self.extra_groups if not _has_geometry_group(name)]
            if wanted:
                try:
                    _, loaded, _unused = _append_from_embedded(
                        self.extra_blend_data_name,
                        lambda names: [name for name in names if name in wanted],
                    )
                    extra_groups = [grp for grp in loaded if grp is not None]
                except Exception as exc:
                    self.report(
                        {'ERROR'},
                        f"Could not read the embedded {label} Geometry Nodes group: {exc}"
                    )

        imported = []

        if sun is not None:
            (context.collection or context.scene.collection).objects.link(sun)
            imported.append("Sun")

        failed = False
        main_group = _find_group(self.main_group, self.main_group_source)
        _rename_groups(self.group_renames, groups, main_group)
        if main_group is not None:
            try:
                mat, action = _apply_shader_material(
                    main_group, context.active_object, self.build_nodes, self.material_name
                )
                imported.append(f"material '{mat.name}' {action}")
            except Exception as exc:
                failed = True
                traceback.print_exc()
                self.report({'ERROR'}, f"Could not build the {label} material: {exc}")

        # Remove the unneeded 'material_preview_dummy' mesh Blender creates
        _remove_preview_dummy()
        _schedule_preview_dummy_cleanup()

        # Keep groups that no material uses (utility groups) when the file is saved
        for grp in groups + extra_groups:
            if grp.users == 0:
                grp.use_fake_user = True
        if groups:
            imported.append(f"{len(groups)} node group(s)")
        if extra_groups:
            imported.append("Geometry Nodes group " + ", ".join(f"'{grp.name}'" for grp in extra_groups))

        if not imported:
            if not failed:
                self.report({'INFO'}, f"The {label} shader is already in this project")
            return {'CANCELLED'}

        self.report({'INFO'}, f"{label} shader imported: " + ", ".join(imported))
        return {'FINISHED'}


class ORGAN_OT_import_strive_shader(_ShaderImportOperator, bpy.types.Operator):
    """Add the Strive node groups and the Sun, and overwrite the active material of the active object with the Strive Shader setup"""
    bl_idname = "organ.import_strive_shader"
    bl_label = "Strive Shader"
    bl_options = {'REGISTER', 'UNDO'}

    shader_label = "Strive"
    blend_data_name = "_STRIVE_SHADER_B64"
    main_group = _STRIVE_MAIN_GROUP
    main_group_source = _STRIVE_MAIN_GROUP_SOURCE
    sun_name = _STRIVE_SUN_NAME
    material_name = _STRIVE_MATERIAL_NAME
    build_nodes = staticmethod(_build_strive_nodes)
    group_renames = _STRIVE_GROUP_RENAMES


