class ORGAN_PT_shader_import(bpy.types.Panel):
    bl_label = "O.R.G.A.N.: Shader Import"
    bl_idname = "ORGAN_PT_shader_import"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "O.R.G.A.N."
    bl_order = 10  # keep this panel below the main O.R.G.A.N. panel whatever the load order

    def draw(self, context):
        layout = self.layout
        layout.operator(ORGAN_OT_import_strive_shader.bl_idname, icon='NODE_MATERIAL')
        layout.operator(ORGAN_OT_import_xrd_shader.bl_idname, icon='NODE_MATERIAL')
        layout.operator(ORGAN_OT_import_decal_shader.bl_idname, icon='NODE_MATERIAL')
        layout.operator(ORGAN_OT_import_outline_shader.bl_idname, icon='NODE_MATERIAL')


classes = (
    ORGAN_OT_import_strive_shader,
    ORGAN_OT_import_xrd_shader,
    ORGAN_OT_import_decal_shader,
    ORGAN_OT_import_outline_shader,
    ORGAN_PT_shader_import,
)


def register():
    for cls in classes:
        bpy.utils.register_class(cls)


def unregister():
    if bpy.app.timers.is_registered(_preview_dummy_tick):
        bpy.app.timers.unregister(_preview_dummy_tick)

    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)


if __name__ == "__main__":
    register()

